import{_ as i,a0 as r,w as p,s as h,ao as s,I as n,x as a,a1 as t,A as l}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const T=JSON.parse('{"title":"Linux who 命令 – 显示系统登录者 | LCTT x X-CMD","titleTemplate":false,"description":"Linux who 命令 – 显示系统登录者 | LCTT (201401) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux who 命令 – 显示系统登录者 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux who 命令 – 显示系统登录者 | LCTT (201401) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201401/Linux who command – Displays who is on the system","title":"Linux who 命令 – 显示系统登录者","tag":"201401","desc":""},"relativePath":"201401/Linux who command – Displays who is on the system.md","filePath":"[post].md"}'),d={name:"201401/Linux who command – Displays who is on the system.md"};function m(w,o,u,x,c,g){const e=r("Link");return p(),h("div",null,[o[13]||(o[13]=s(`<h1 id="linux-who-命令-–-显示系统登录者" tabindex="-1">Linux who 命令 – 显示系统登录者 <a class="header-anchor" href="#linux-who-命令-–-显示系统登录者" aria-label="Permalink to “Linux who 命令 – 显示系统登录者”">​</a></h1><p>作为一名系统管理员，我们需要弄清楚在一个特定的时间点都有谁活跃在系统上。必须严密监视我们的服务器。但是，我们当然不可能一天24小时都盯着系统。在linux系统中，我们可以使用who命令查看登录者信息。</p><h3 id="什么是-who-命令" tabindex="-1">什么是 who 命令 <a class="header-anchor" href="#什么是-who-命令" aria-label="Permalink to “什么是 who 命令”">​</a></h3><p><strong>who</strong>命令能够打印 <strong>当前都有谁登录到系统中</strong> 的相关信息 。who命令只会显示真正登录到系统中的用户。它不会显示那些通过<strong>su</strong>命令切换用户的登录者。</p><h3 id="如何使用who命令" tabindex="-1">如何使用who命令 <a class="header-anchor" href="#如何使用who命令" aria-label="Permalink to “如何使用who命令”">​</a></h3><p>在大多数linux发行版中，who命令都是默认安装上的。想使用该命令，只需在控制台敲命令就行了。不带选项的话，运行该命令产生默认输出。</p><pre><code>$ who
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2013/12/who_default.png" alt=""></p><h4 id="如何理解输出" tabindex="-1">如何理解输出: <a class="header-anchor" href="#如何理解输出" aria-label="Permalink to “如何理解输出:”">​</a></h4><ul><li>第一列显示用户名称</li><li>第二列显示用户连接方式。Tty意味着用户直接连接到电脑上，而pts意味着远程登录。</li><li>第三、四列分别显示日期和时间</li><li>第五列显示用户登录IP地址。</li></ul><h3 id="使用带参数的who命令" tabindex="-1">使用带参数的who命令 <a class="header-anchor" href="#使用带参数的who命令" aria-label="Permalink to “使用带参数的who命令”">​</a></h3><p>Who命令有一些参数用于调整输出。以下是常用的例子。</p><h4 id="显示上一次重新启动的时间和日期" tabindex="-1">显示上一次重新启动的时间和日期 <a class="header-anchor" href="#显示上一次重新启动的时间和日期" aria-label="Permalink to “显示上一次重新启动的时间和日期”">​</a></h4><p>使用 <strong>-b</strong> 选项</p><pre><code>$ who -b
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2013/12/who_b.png" alt=""></p><p>可以看到系统启动是在2013年12月21日，下午3:52。</p><h4 id="显示初始化进程的当前运行级别" tabindex="-1">显示初始化进程的当前运行级别 <a class="header-anchor" href="#显示初始化进程的当前运行级别" aria-label="Permalink to “显示初始化进程的当前运行级别”">​</a></h4><p>使用 -r 选项，who命令会打印出初始化进程的当前运行级别</p><pre><code>$ who -r
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2013/12/who_r.png" alt=""></p><p>输出显示2013年12月21日，下午3:52系统以 级别2 开始运行。</p><h4 id="为每一列添加标题" tabindex="-1">为每一列添加标题 <a class="header-anchor" href="#为每一列添加标题" aria-label="Permalink to “为每一列添加标题”">​</a></h4><p>使用 -H 选项为每一列添加标题</p><pre><code>$ who -H
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2013/12/who_H.png" alt=""></p><h4 id="只打印当前运行终端的相关信息" tabindex="-1">只打印当前运行终端的相关信息 <a class="header-anchor" href="#只打印当前运行终端的相关信息" aria-label="Permalink to “只打印当前运行终端的相关信息”">​</a></h4><p>可以使用<strong>-m</strong>选项。</p><pre><code>$ who -m
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2013/12/who_m.png" alt=""></p><h4 id="对当前登录用户数量计数" tabindex="-1">对当前登录用户数量计数 <a class="header-anchor" href="#对当前登录用户数量计数" aria-label="Permalink to “对当前登录用户数量计数”">​</a></h4><p>如果系统同时有多人登录在线，-q 选项协助你完成计数功能。</p><pre><code>$ who -q
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2013/12/who_q.png" alt=""></p><h4 id="附加空闲时间和pid信息" tabindex="-1">附加空闲时间和PID信息 <a class="header-anchor" href="#附加空闲时间和pid信息" aria-label="Permalink to “附加空闲时间和PID信息”">​</a></h4><p>默认情况下，who命令不会打印空闲时间和PID信息。如果打算显示这些信息，使用-u选项。不要忘记使用 -H选项让显示的信息更加简单易读。</p><pre><code>$ who -u -H
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2013/12/who_u.png" alt=""></p><p><strong>空闲时间</strong> 包含了最近最后一次活动以来消逝的时间. 所以，00:13 意思是 用户leni已经13分钟没执行过命令了. <strong>(.)符号</strong> 是指该终端过去的一分钟有过活动。在那期间，我们称之为 “current” 。<strong>PID</strong> 是用户shell程序的进程ID号。</p><h4 id="显示登录进程" tabindex="-1">显示登录进程#### <a class="header-anchor" href="#显示登录进程" aria-label="Permalink to “显示登录进程####”">​</a></h4><p>使用<strong>-l</strong>选项</p><pre><code>$ who -l
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2013/12/who_l.png" alt=""></p><p>第一列只显示系统登录守护进程的名字。上面截图中的数字 967, 971等是进程ID。</p><h4 id="显示所有信息" tabindex="-1">显示所有信息 <a class="header-anchor" href="#显示所有信息" aria-label="Permalink to “显示所有信息”">​</a></h4><p>使用<strong>-a</strong>选项会显示所有信息。例如：</p><pre><code>$ who -a
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2013/12/who_a.png" alt=""></p><p>####总结#### 你会发现 who 命令跟 w 命令在某些方面有些相像。不要为此感到疑惑，为什么linux要实现这些在功能上相近的命令。你可以使用你觉得最适合你的或者适用于某种场合的命令。请查阅who命令手册了解更多详细信息。</p>`,49)),n("ul",null,[n("li",null,[o[1]||(o[1]=a("See more at: ",-1)),t(e,{href:"http://linoxide.com/linux-command/linux-who-command/#sthash.CU0bq3e4.dpuf"},{default:l(()=>[...o[0]||(o[0]=[a("http://linoxide.com/linux-command/linux-who-command/#sthash.CU0bq3e4.dpuf",-1)])]),_:1})])]),o[14]||(o[14]=n("hr",null,null,-1)),n("p",null,[o[3]||(o[3]=a("via: ",-1)),t(e,{href:"http://linoxide.com/linux-command/linux-who-command/"},{default:l(()=>[...o[2]||(o[2]=[a("http://linoxide.com/linux-command/linux-who-command/",-1)])]),_:1})]),n("p",null,[o[6]||(o[6]=a("译者：",-1)),t(e,{href:"https://github.com/l3b2w1"},{default:l(()=>[...o[4]||(o[4]=[a("l3b2w1",-1)])]),_:1}),o[7]||(o[7]=a(" 校对：",-1)),t(e,{href:"https://github.com/carolinewuyan"},{default:l(()=>[...o[5]||(o[5]=[a("Caroline",-1)])]),_:1})]),n("p",null,[o[10]||(o[10]=a("本文由 ",-1)),t(e,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...o[8]||(o[8]=[a("LCTT",-1)])]),_:1}),o[11]||(o[11]=a(" 原创翻译，",-1)),t(e,{href:"http://linux.cn/"},{default:l(()=>[...o[9]||(o[9]=[a("Linux中国",-1)])]),_:1}),o[12]||(o[12]=a(" 荣誉推出",-1))])])}const P=i(d,[["render",m]]);export{T as __pageData,P as default};
